# Mock clock function for testing
def mock_now(timestamp):
    return timestamp

# --- Test Case 1: Initialization and Full Bucket ---
capacity = 10
refill = 2
now_time = 1000000000000 # Mock time
tb = TokenBucket(options={'capacity': capacity, 'refillPerSecond': refill, 'now': mock_now})

# Should start full
assert tb.available() == capacity

# --- Test Case 2: Taking Tokens ---
tb.tryTake(5)
assert tb.available() == 5.0

tb.tryTake(10) # Should fail
assert tb.available() == 5.0

# --- Test Case 3: Refill (1 second passes) ---
# Manually set time forward for testing refill mechanism
new_time = 1000000001000
tb._refill(new_time)
assert tb.available() == 7.0 # 5 + 2 = 7

# --- Test Case 4: Time going backward ---
tb._refill(1000000000500) # Time goes backward, no refill should happen
assert tb.available() == 7.0

# --- Test Case 5: RangeError checks ---
try:
    TokenBucket(options={'capacity': -1})
    assert False, "Should have thrown RangeError for negative capacity"
except RangeError:
    pass

try:
    TokenBucket(options={'refillPerSecond': -1})
    assert False, "Should have thrown RangeError for negative refill"
except RangeError:
    pass

try:
    tb_test = TokenBucket(options={'capacity': 1, 'refillPerSecond': 1, 'now': mock_now})
    tb_test.tryTake(0)
    assert False, "Should have thrown RangeError for n=0"
except RangeError:
    pass

print("All tests passed successfully.")

